"""Registration, discovery, lookup and the export entry points."""

from __future__ import annotations

import importlib
import io
import pkgutil
import re

from xport.formats.base import Context, Format, Option, OptionError, RegistryError, UnknownFormatError

__all__ = ["register", "discover", "lookup", "resolve", "list_formats", "export", "export_text"]

_KEY = re.compile(r"[a-z][a-z0-9]*\Z")
_BOOL = {"true": True, "yes": True, "on": True, "1": True, "false": False, "no": False, "off": False, "0": False}
_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_.-]*\Z")
_WHOLE = re.compile(r"[+-]?[0-9]+\Z")
_SKIP = {"base", "registry", "common"}

_keys: dict[str, tuple[Format, str]] = {}
_formats: list[Format] = []
_discovered = False


def register(cls):
    """Class decorator: registers one instance of a Format subclass."""
    module = cls.__module__
    seen: dict[str, str] = {}
    for key in (cls.name, *cls.aliases):
        if not isinstance(key, str) or not _KEY.match(key):
            raise RegistryError(f"format name '{key}' in {module} is not a valid name")
        holder = seen.get(key) or (_keys[key][1] if key in _keys else None)
        if holder is not None:
            raise RegistryError(f"format name '{key}' is claimed by {holder} and {module}")
        seen[key] = module
    instance = cls()
    _formats.append(instance)
    for key in seen:
        _keys[key] = (instance, module)
    return cls


def discover() -> None:
    """Imports every plugin module of the package, once."""
    global _discovered
    if _discovered:
        return
    package = importlib.import_module("xport.formats")
    names = sorted(
        info.name
        for info in pkgutil.iter_modules(package.__path__)
        if not info.ispkg and not info.name.startswith("_") and info.name not in _SKIP
    )
    first = None
    for name in names:
        try:
            importlib.import_module(f"xport.formats.{name}")
        except RegistryError as exc:
            if first is None:
                first = exc
    if first is not None:
        raise first
    _discovered = True


def _listing() -> list[Format]:
    discover()
    return sorted(_formats, key=lambda f: (f.order, f.name))


def lookup(name: str) -> Format:
    discover()
    entry = _keys.get(name.strip().lower())
    if entry is None:
        known = ", ".join(f.name for f in _listing())
        raise UnknownFormatError(f"unknown format '{name}' (known: {known})")
    return entry[0]


def resolve(name: str) -> str:
    return lookup(name).name


def list_formats() -> list[tuple[str, tuple[str, ...], str]]:
    return [(f.name, tuple(f.aliases), f.summary) for f in _listing()]


def _convert(invoked: str, opt: Option, text: str):
    where = f"option '{opt.name}' of format '{invoked}'"
    kind = opt.kind
    if kind == "bool":
        value = _BOOL.get(text.lower())
        if value is None:
            raise OptionError(f"{where} takes true or false, not '{text}'")
        return value
    if kind == "int":
        if not _WHOLE.match(text):
            raise OptionError(f"{where} takes a whole number, not '{text}'")
        n = int(text)
        if opt.low is not None and n < opt.low:
            raise OptionError(f"{where} must be at least {opt.low}")
        if opt.high is not None and n > opt.high:
            raise OptionError(f"{where} must be at most {opt.high}")
        return n
    if kind == "char":
        if text in ("tab", "\\t"):
            return "\t"
        if text == "space":
            return " "
        if len(text) != 1:
            raise OptionError(f"{where} takes a single character, not '{text}'")
        return text
    if kind == "choice":
        if text not in opt.choices:
            raise OptionError(f"{where} takes one of {'|'.join(opt.choices)}, not '{text}'")
        return text
    if kind == "name":
        if not _NAME.match(text):
            raise OptionError(f"{where} takes a name (letters, digits, _ . -), not '{text}'")
        return text
    return text


def _context(fmt: Format, invoked: str, pairs, out) -> Context:
    specs = fmt.options
    known = {opt.name for opt in specs}
    raw = {}
    for pair in pairs:
        key, sep, value = pair.partition("=")
        key = key.strip()
        if not sep or not key:
            raise OptionError(f"option '{pair}' is not key=value")
        if key not in known:
            names = ", ".join(opt.name for opt in specs) or "none"
            raise OptionError(f"format '{invoked}' has no option '{key}' (options: {names})")
        raw[key] = value
    values = {}
    for opt in specs:
        if opt.name in raw:
            values[opt.name] = _convert(invoked, opt, raw[opt.name])
        else:
            values[opt.name] = opt.default
    return Context(invoked, values, frozenset(raw), out)


def export(table, fmt_name: str, options=(), out=None) -> None:
    """Writes table to the text stream out in the named format."""
    fmt = lookup(fmt_name)
    ctx = _context(fmt, fmt_name, options, out)
    fmt.check(ctx)
    fmt.write(table, ctx)


def export_text(table, fmt_name: str, options=()) -> str:
    """export() into a string."""
    buf = io.StringIO(newline="")
    export(table, fmt_name, options, buf)
    return buf.getvalue()
