"""Helpers shared by several plugins."""

from __future__ import annotations

from datetime import datetime
from decimal import ROUND_HALF_EVEN, Decimal

NUMERIC = ("int", "dec")


def quant(value: Decimal, scale: int) -> str:
    return str(value.quantize(Decimal(1).scaleb(-scale), rounding=ROUND_HALF_EVEN))


def wall(value: datetime) -> str:
    return value.strftime("%Y-%m-%d %H:%M:%S")


def plain_cell(col, value, tag_sep: str, true: str = "true", false: str = "false"):
    """Text of a non-missing value for the formats that write the common way."""
    kind = col.type
    if kind == "tags":
        return tag_sep.join(value)
    if kind == "str":
        return value
    if kind == "bool":
        return true if value else false
    if kind == "int":
        return str(value)
    if kind == "dec":
        return quant(value, col.scale)
    if kind == "date":
        return value.isoformat()
    return wall(value)
